from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')

# Add controls for imported material.
if 'id="playImportedBtn"' not in s:
    marker='''    <div class="uploadinfo" id="uploadInfo">Keine Vorlage geladen.</div>\n\n    <button class="primary" id="composeBtn">Mit gewählter KI komponieren</button>'''
    repl='''    <div class="uploadinfo" id="uploadInfo">Keine Vorlage geladen.</div>\n    <div class="toolbar" style="margin-top:8px;">\n      <button type="button" class="secondary smallbtn" id="playImportedBtn" disabled>▶ Im Player anhören</button>\n      <button type="button" class="secondary smallbtn" id="analyzeImportedBtn" disabled>Mit KI analysieren</button>\n    </div>\n    <div id="importedAnalysis" class="resultcard" style="display:none;margin-top:8px;white-space:pre-wrap;">Noch keine Analyse.</div>\n\n    <button class="primary" id="composeBtn">Mit gewählter KI komponieren</button>'''
    if marker not in s: raise SystemExit('upload UI marker not found')
    s=s.replace(marker,repl,1)

# When a MIDI/JSON is imported, make it immediately available in the main player.
old='''    const count = (uploadedScore.tr||[]).reduce((s,t)=>s+(t.nt?.length||0), 0);\n    $("uploadInfo").textContent = `Geladen: ${f.name} (${count} Noten)`;\n    $("status").textContent = "Material geladen. Wird als Referenz mitgesendet.";'''
new='''    const count = (uploadedScore.tr||[]).reduce((s,t)=>s+(t.nt?.length||0), 0);\n    $("uploadInfo").textContent = `Geladen: ${f.name} (${count} Noten)`;\n    mainPlayerScore = uploadedScore;\n    if($("mainPlayerTitle")) $("mainPlayerTitle").textContent = `Import: ${f.name}`;\n    if($("playerSeek")) $("playerSeek").value = "0";\n    if($("playerTime")) $("playerTime").textContent = "0:00 / 0:00";\n    if($("playerStatus")) $("playerStatus").textContent = `Import „${f.name}“ im Hauptplayer bereit.`;\n    if($("playImportedBtn")) $("playImportedBtn").disabled = false;\n    if($("analyzeImportedBtn")) $("analyzeImportedBtn").disabled = false;\n    if($("importedAnalysis")){ $("importedAnalysis").style.display="none"; $("importedAnalysis").textContent="Noch keine Analyse."; }\n    $("status").textContent = "Material geladen. Es kann angehört, analysiert und als Referenz mitgesendet werden.";'''
if old not in s: raise SystemExit('upload success marker not found')
s=s.replace(old,new,1)

# Clear import controls together with the imported score.
old='''  uploadedScore = null;\n  $("uploadInput").value = "";\n  $("uploadInfo").textContent = "Keine Vorlage geladen.";'''
new='''  uploadedScore = null;\n  $("uploadInput").value = "";\n  $("uploadInfo").textContent = "Keine Vorlage geladen.";\n  if($("playImportedBtn")) $("playImportedBtn").disabled = true;\n  if($("analyzeImportedBtn")) $("analyzeImportedBtn").disabled = true;\n  if($("importedAnalysis")){ $("importedAnalysis").style.display="none"; $("importedAnalysis").textContent="Noch keine Analyse."; }'''
if old in s: s=s.replace(old,new,1)

# Add imported-material playback and AI analysis logic.
if 'imported-midi-analysis-v9' not in s:
    script='''\n<script id="imported-midi-analysis-v9">\n(()=>{\n  const playBtn=document.getElementById("playImportedBtn");\n  const analyseBtn=document.getElementById("analyzeImportedBtn");\n  const box=document.getElementById("importedAnalysis");\n\n  if(playBtn) playBtn.addEventListener("click",()=>{\n    if(!uploadedScore){\n      document.getElementById("status").innerHTML='<span class="err">Bitte zuerst eine MIDI- oder JSON-Datei laden.</span>';\n      return;\n    }\n    mainPlayerScore=uploadedScore;\n    if(document.getElementById("mainPlayerTitle")) document.getElementById("mainPlayerTitle").textContent=`Import: ${uploadedName||uploadedScore.ti||"MIDI-Datei"}`;\n    playGMScore(uploadedScore,0).catch(err=>{document.getElementById("status").innerHTML=`<span class="err">${esc(err.message)}</span>`});\n  });\n\n  if(analyseBtn) analyseBtn.addEventListener("click",async()=>{\n    if(!uploadedScore){\n      document.getElementById("status").innerHTML='<span class="err">Bitte zuerst eine MIDI- oder JSON-Datei laden.</span>';\n      return;\n    }\n    const provider=document.getElementById("provider").value;\n    const model=document.getElementById("model").value.trim();\n    const apiKeyVal=document.getElementById("apiKey").value.trim();\n    if(!apiKeyVal){\n      document.getElementById("status").innerHTML='<span class="err">Bitte zuerst den API-Key der gewählten KI eingeben.</span>';\n      return;\n    }\n    analyseBtn.disabled=true;\n    box.style.display="block";\n    box.textContent="KI analysiert die importierte MIDI-Datei …";\n    try{\n      const task=`Analysiere die folgende importierte MIDI-Komposition musikalisch und nicht nur technisch. Untersuche insbesondere:\n- Form und Spannungsverlauf\n- Hauptmotive und ihre Entwicklung\n- Melodik und Phrasierung\n- Harmonik und Tonalität\n- Rhythmik und Metrik\n- Begleitmuster und Satzstruktur\n- Stimmführung bzw. Zusammenspiel der Instrumente\n- Dynamik und Artikulation, soweit aus den MIDI-Daten erkennbar\n- charakteristische Stärken und mögliche handwerkliche oder musikalische Schwächen\n- konkrete Möglichkeiten zur Weiterentwicklung, Variation oder Fortsetzung\n\nTrenne Beobachtung und Bewertung sauber. Erfinde nichts, was aus den MIDI-Daten nicht ableitbar ist. Beziehe dich bei wichtigen Aussagen möglichst konkret auf musikalische Ereignisse oder Abschnitte.\n\nDATEI: ${uploadedName||uploadedScore.ti||"Import"}\n\nMIDI-DATEN:\n${JSON.stringify(uploadedScore)}`;\n      const res=await callLLM(provider,model,apiKeyVal,SYSTEM_PREFIX,task,false);\n      box.textContent=res.text||"Die KI hat keine Analyse zurückgegeben.";\n      document.getElementById("status").innerHTML='<span class="ok">Analyse der importierten MIDI-Datei erstellt.</span>';\n    }catch(err){\n      box.innerHTML=`<span class="err">${esc(err.message)}</span>`;\n      document.getElementById("status").innerHTML=`<span class="err">Analyse fehlgeschlagen: ${esc(err.message)}</span>`;\n    }finally{\n      analyseBtn.disabled=false;\n    }\n  });\n})();\n</script>\n'''
    s=s.replace('</body>',script+'\n</body>',1)

s=s.replace('navigator.serviceWorker.register("./service-worker.js?v=10")','navigator.serviceWorker.register("./service-worker.js?v=11")')
p.write_text(s,encoding='utf-8')
